<map version="1.0.1"><node CREATED="1747229326053" ID="ID_root" MODIFIED="1747229326053" TEXT="03_函数"><node CREATED="1747229326053" ID="ID_964dc29e710ef47d" POSITION="right" MODIFIED="1747229326053" TEXT="函数概述"><node CREATED="1747229326053" ID="ID_7ba418aa2ab8d3f7" MODIFIED="1747229326053" TEXT="什么是函数。函数就是将一些逻辑写在一起，后续需要使用使用这些逻辑直接使用。不用重复写"></node><node CREATED="1747229326053" ID="ID_88d7edde7e35b84d" MODIFIED="1747229326053" TEXT="比如，一个游戏公司，可能会有大量的三角形面积的计算。比如传三个边，算面积出来；&amp;nbsp;这时候，反复写相同一段代码，不太好。&amp;lt;br&amp;gt;采用的是，直接复用一段逻辑，这个就是函数"><node CREATED="1747229326053" ID="ID_104e3badb2464699" MODIFIED="1747229326053" TEXT="函数可以应对功能的修改。&amp;nbsp;"></node><node CREATED="1747229326053" ID="ID_414124abf446c967" MODIFIED="1747229326053" TEXT="Case1:&amp;nbsp;如果计算三角形的面积公式，我们将这些代码每次都拷着跑。&amp;nbsp;&amp;lt;br&amp;gt;有1000处一模一样的逻辑。&amp;nbsp;"></node><node CREATED="1747229326053" ID="ID_6c257235644c4776" MODIFIED="1747229326053" TEXT="学校的某一个底层系统。&amp;nbsp;对于学生分等级。&amp;nbsp;比如分数有几个等级&amp;nbsp;&amp;lt;br&amp;gt;[0,60) ==&amp;gt;&amp;nbsp;差&amp;lt;br&amp;gt;[60,80) ===&amp;gt;&amp;nbsp;一般&amp;lt;br&amp;gt;[80, 90)===&amp;gt;&amp;nbsp;良&amp;lt;br&amp;gt;[90,100] ===&amp;gt;&amp;nbsp;优秀"><node CREATED="1747229326053" ID="ID_0dd60da211f86411" MODIFIED="1747229326053" TEXT="假设有人写代码，完全不复用函数。&amp;nbsp;直接代码逻辑复制到处跑&amp;lt;br&amp;gt;假设系统里面有50处这种判断逻辑"></node><node CREATED="1747229326053" ID="ID_7ac476398fbab06d" MODIFIED="1747229326053" TEXT="学校的某一个底层系统。&amp;nbsp;对于学生分等级。&amp;nbsp;比如分数有几个等级&amp;nbsp;&amp;lt;br&amp;gt;[0,60) ==&amp;gt;&amp;nbsp;进步空间巨大&amp;lt;br&amp;gt;[60,70) ===&amp;gt;&amp;nbsp;比较优秀&amp;lt;br&amp;gt;[70, 80)===&amp;gt;&amp;nbsp;很棒&amp;lt;br&amp;gt;[80,100] ===&amp;gt;&amp;nbsp;非常棒"></node></node><node CREATED="1747229326053" ID="ID_f792031d719b2426" MODIFIED="1747229326053" TEXT="double calculate_triangle_area(){"></node></node><node CREATED="1747229326053" ID="ID_5b3a5b9989453276" MODIFIED="1747229326053" TEXT="面试题一般是这样的：&amp;nbsp;简单说说函数的好处&amp;lt;br&amp;gt;为什么要使用函数&amp;lt;br&amp;gt;函数的必要性"><node CREATED="1747229326053" ID="ID_7aebcd6cf3ecebe1" MODIFIED="1747229326053" TEXT="建议写代码的时候，思考一下，能不能提函数，让功能复用一下。"></node></node><node CREATED="1747229326053" ID="ID_fe89348fd64d7b4c" MODIFIED="1747229326053" TEXT="函数分类"><node CREATED="1747229326053" ID="ID_4f4e9df25a22d250" MODIFIED="1747229326053" TEXT="官方写好的，我们直接用的叫库函数"></node><node CREATED="1747229326053" ID="ID_29cbec306f9c0cf9" MODIFIED="1747229326053" TEXT="我们自己写的叫做&amp;nbsp;用户自定义函数&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229326053" ID="ID_7d0880184ab11783" MODIFIED="1747229326053" TEXT="为什么使用函数这个也非常重要"></node></node><node CREATED="1747229326053" ID="ID_827c82565ee8617d" POSITION="right" MODIFIED="1747229326053" TEXT="函数的使用"><node CREATED="1747229326053" ID="ID_3f310d75a1be2923" MODIFIED="1747229326053" TEXT="定义一个函数的语法"><node CREATED="1747229326053" ID="ID_cda193a1720d9bfa" MODIFIED="1747229326053" TEXT="返回值&amp;nbsp;函数名(形参){&amp;lt;br&amp;gt;函数体&amp;lt;br&amp;gt;}"></node><node CREATED="1747229326053" ID="ID_78590db4f0b1fd44" MODIFIED="1747229326053" TEXT="有一些特殊的概念，&amp;lt;br&amp;gt;在C中有特殊含义"><node CREATED="1747229326053" ID="ID_37f480191a62000e" MODIFIED="1747229326053" TEXT="函数头"><node CREATED="1747229326053" ID="ID_97aeecb9d5050c87" MODIFIED="1747229326053" TEXT="就是只有最前面部分&amp;lt;br&amp;gt;int test1(int num)"></node></node><node CREATED="1747229326053" ID="ID_89aa1f6103151842" MODIFIED="1747229326053" TEXT="函数定义"><node CREATED="1747229326053" ID="ID_923bc96e33df0a25" MODIFIED="1747229326053" TEXT="就是函数的全部部分"></node></node><node CREATED="1747229326053" ID="ID_a16125c4e1847542" MODIFIED="1747229326053" TEXT="函数体"><node CREATED="1747229326053" ID="ID_ad3556b5978eb972" MODIFIED="1747229326053" TEXT="只有大括号里面的内容"></node></node><node CREATED="1747229326053" ID="ID_7cb97aba2ea061be" MODIFIED="1747229326053" TEXT="函数声明"><node CREATED="1747229326053" ID="ID_1fbfcf7e35d1221e" MODIFIED="1747229326053" TEXT="函数头加分号"></node></node></node></node><node CREATED="1747229326053" ID="ID_0eb4bea2059937d1" MODIFIED="1747229326053" TEXT="函数调用方式"></node><node CREATED="1747229326054" ID="ID_c98f835707fed850" MODIFIED="1747229326054" TEXT="函数的定义顺序影响调用。也就是说，要被调用的函数要写在上面"><node CREATED="1747229326054" ID="ID_2ec532e1efa16962" MODIFIED="1747229326054" TEXT="或者说，在前面先写上函数声明"></node></node><node CREATED="1747229326054" ID="ID_3798fc558e4dfb0a" MODIFIED="1747229326054" TEXT="函数的设计原则"><node CREATED="1747229326054" ID="ID_26f0dbc78b680ad8" MODIFIED="1747229326054" TEXT="遵循单一原则。这样可以让函数能复用"></node></node></node><node CREATED="1747229326054" ID="ID_757532e88fed0a17" POSITION="right" MODIFIED="1747229326054" TEXT="一个特殊的退出函数"><node CREATED="1747229326054" ID="ID_bf645eddcf15d708" MODIFIED="1747229326054" TEXT="exit"></node><node CREATED="1747229326054" ID="ID_e737789f30ca1a2b" MODIFIED="1747229326054" TEXT="顺便讲了退出码"><node CREATED="1747229326054" ID="ID_52bbc5b5eadb5b32" MODIFIED="1747229326054" TEXT="0用来表示程序正常退出&amp;lt;br&amp;gt;其他的都是不正常"></node><node CREATED="1747229326054" ID="ID_85372dd22496d055" MODIFIED="1747229326054" TEXT="EXIT_SUCCESS &amp;lt;br&amp;gt;EXIT_FAILURE&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229326054" ID="ID_a7bec8ad040206e6" POSITION="right" MODIFIED="1747229326054" TEXT="变量的分类"><node CREATED="1747229326054" ID="ID_c2d02d05c0361c8e" MODIFIED="1747229326054" TEXT="局部变量"><node CREATED="1747229326054" ID="ID_f8fe9a7a56149827" MODIFIED="1747229326054" TEXT="局部变量是存储在栈帧中的"></node><node CREATED="1747229326054" ID="ID_2c29910c6f0e0e6d" MODIFIED="1747229326054" TEXT="要调用一个函数，就要创建栈帧，并且将栈帧压入栈中"><node CREATED="1747229326054" ID="ID_fbdb5a3d7c316280" MODIFIED="1747229326054" TEXT="一定要知道栈是什么东西：&amp;nbsp;操作受限的线性表，只能在一端进出，数据表现为后进先出。"></node><node CREATED="1747229326054" ID="ID_af4adec61f0758d7" MODIFIED="1747229326054" TEXT="1.函数的调用是有代价的，代价是会创建一个栈帧。"></node><node CREATED="1747229326054" ID="ID_a90afc69a2a78d80" MODIFIED="1747229326054" TEXT="2.每当要调用一个函数的时候，都要创建一个栈帧，并且将这个栈帧压栈。&amp;lt;br&amp;gt;只有栈顶的栈帧的局部变量才会生效。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229326054" ID="ID_ed1ca131bf7d78b2" MODIFIED="1747229326054" TEXT="3.当一个函数执行结束，这时候栈顶的栈帧弹栈。&amp;nbsp;这些局部变量就自然失效了。"></node><node CREATED="1747229326054" ID="ID_02e81670d08ee78e" MODIFIED="1747229326054" TEXT="细节"><node CREATED="1747229326054" ID="ID_720d9184524f0880" MODIFIED="1747229326054" TEXT="1.弹栈的时候，是否需要完成清空这块内存。&amp;nbsp;&amp;lt;br&amp;gt;在真实的实践中，我们完全可以用一个int来标识栈顶的位置，出栈的时候，只需要改这个int。&amp;nbsp;&amp;lt;br&amp;gt;这个时候，速度就会非常快"></node><node CREATED="1747229326054" ID="ID_f9c9a884861f4469" MODIFIED="1747229326054" TEXT="2.栈帧里面只存局部变量吗？&amp;lt;br&amp;gt;栈帧里面还会存储，返回的地址（也就是下一行执行哪个代码）&amp;lt;br&amp;gt;返回值也会存储在这里"></node><node CREATED="1747229326054" ID="ID_8ca01c4c71fc4844" MODIFIED="1747229326054" TEXT="如果了解的话，对你理解程序更有帮助。&amp;nbsp;"></node></node></node><node CREATED="1747229326054" ID="ID_e94e0be4a2192a94" MODIFIED="1747229326054" TEXT="一定要理解函数的调用过程。重点"></node><node CREATED="1747229326054" ID="ID_0cf6e215f4f512ef" MODIFIED="1747229326054" TEXT="只要理解了函数的调用过程，局部变量的特点就知道。&amp;nbsp;随着栈同生共死"></node><node CREATED="1747229326054" ID="ID_97fc4461ea48bc7d" MODIFIED="1747229326054" TEXT="栈区数据的优点缺点"><node CREATED="1747229326054" ID="ID_8e4a15564aa9135e" MODIFIED="1747229326054" TEXT="优点"><node CREATED="1747229326054" ID="ID_18acf4183e3d6a87" MODIFIED="1747229326054" TEXT="简单高效。"></node><node CREATED="1747229326054" ID="ID_dd81c0419491b321" MODIFIED="1747229326054" TEXT="自动管理内存"></node></node><node CREATED="1747229326054" ID="ID_c3561a1de4f335a5" MODIFIED="1747229326054" TEXT="缺点"><node CREATED="1747229326054" ID="ID_b7b4543a7f02fc36" MODIFIED="1747229326054" TEXT="内存小。&amp;nbsp;"></node><node CREATED="1747229326054" ID="ID_4627b96c25da0286" MODIFIED="1747229326054" TEXT="为了保证简单高效，栈帧大小需要在编译时确定。&amp;nbsp;&amp;lt;br&amp;gt;所以不具有动态性。"></node></node></node></node><node CREATED="1747229326054" ID="ID_a0485e5f89c41411" MODIFIED="1747229326054" TEXT="全局变量"><node CREATED="1747229326054" ID="ID_acd58f062c32f0ab" MODIFIED="1747229326054" TEXT="存储在数据段上。&amp;nbsp;"></node><node CREATED="1747229326054" ID="ID_6dfbf55f10a1c188" MODIFIED="1747229326054" TEXT="生命周期就是跟着程序同生共死。&amp;nbsp;"></node><node CREATED="1747229326054" ID="ID_3f455b191cab6a69" MODIFIED="1747229326054" TEXT="尽量不要用。&amp;nbsp;"><node CREATED="1747229326054" ID="ID_62def124f5c5161e" MODIFIED="1747229326054" TEXT="名字要注意一下。 global_***"></node><node CREATED="1747229326054" ID="ID_fefbee30e4727cfe" MODIFIED="1747229326054" TEXT="如果实在要用，先考虑用静态全局变量。&amp;lt;br&amp;gt;在全局变量前面加static。&amp;nbsp;"></node></node></node><node CREATED="1747229326054" ID="ID_154cdc944c0e0f4f" MODIFIED="1747229326054" TEXT="静态全局变量"><node CREATED="1747229326054" ID="ID_ddeca6227a134f69" MODIFIED="1747229326054" TEXT="加了static的全局变量"></node><node CREATED="1747229326054" ID="ID_b6c58024c8a3e0f6" MODIFIED="1747229326054" TEXT="在当前文件中能访问。其他文件中访问不了"></node></node><node CREATED="1747229326054" ID="ID_00ed026ccc0db69e" MODIFIED="1747229326054" TEXT="静态局部变量"><node CREATED="1747229326054" ID="ID_a92e3af68b601116" MODIFIED="1747229326054" TEXT="局部变量 + static"></node><node CREATED="1747229326054" ID="ID_60d72fe7bacf86d1" MODIFIED="1747229326054" TEXT="存储的位置发生了变化。存储在数据段上&amp;lt;br&amp;gt;生命周期：&amp;nbsp;程序活着就活着，活的很久"></node><node CREATED="1747229326054" ID="ID_d8d17ebae51bb296" MODIFIED="1747229326054" TEXT="初始化"><node CREATED="1747229326054" ID="ID_2fb1fd19e8cba645" MODIFIED="1747229326054" TEXT="如果没有手动初始化，为0值；&amp;lt;br&amp;gt;如果手动初始化了，只会初始化1次"></node></node></node><node CREATED="1747229326054" ID="ID_78b0dacf853a501f" MODIFIED="1747229326054" TEXT="关于如何选择这些变量"><node CREATED="1747229326054" ID="ID_64d8f425077cd3d8" MODIFIED="1747229326054" TEXT="1.建议优先选局部变量。&amp;nbsp;在工作过程中，90%都是用它，&amp;lt;br&amp;gt;没有其他特殊的场景，不要想着用其他的。&amp;nbsp;&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229326054" ID="ID_5ed736f1d3c430d9" MODIFIED="1747229326054" TEXT="2.如果要在多个函数之间共享数据，先考虑一下传参能不能解决。&amp;lt;br&amp;gt;&amp;nbsp;如果解决不了，这时候先考虑静态全局变量。（因为可以限制在一个文件内部使用，其他地方不能用）"></node><node CREATED="1747229326054" ID="ID_6b5ec9d73333b561" MODIFIED="1747229326054" TEXT="3.最后再考虑全局变量。&amp;nbsp;"></node></node></node><node CREATED="1747229326054" ID="ID_dc536a52ec21f66c" POSITION="right" MODIFIED="1747229326054" TEXT="值传递"><node CREATED="1747229326054" ID="ID_28fd592b5532b9bc" MODIFIED="1747229326054" TEXT="C在函数调用过程中，传参的行为问题。&amp;nbsp;"></node><node CREATED="1747229326054" ID="ID_21bbf7b186ec995e" MODIFIED="1747229326054" TEXT="都是值传递，简单说，就是会将参数的值复制一份，传入函数内部。"></node><node CREATED="1747229326054" ID="ID_df0edc58938fe2e7" MODIFIED="1747229326054" TEXT="所以我们在函数内部改参数，不会影响外部的"></node></node><node CREATED="1747229326054" ID="ID_1a5cc7ca89aac4c9" POSITION="right" MODIFIED="1747229326054" TEXT="递归"><node CREATED="1747229326054" ID="ID_0f013b15131df62d" MODIFIED="1747229326054" TEXT="就是函数自己调用自己的一个特殊用法。&amp;nbsp;但是递归在解决一些问题的分解时比较容易"></node><node CREATED="1747229326054" ID="ID_84d123cd88aa97ac" MODIFIED="1747229326054" TEXT="要知道递归的优点和缺点"><node CREATED="1747229326054" ID="ID_ae937950242b855b" MODIFIED="1747229326054" TEXT="优点：&amp;nbsp;代码简洁、容易理解"></node><node CREATED="1747229326054" ID="ID_bd258429cd86b8c4" MODIFIED="1747229326054" TEXT="缺点：&amp;nbsp;占用栈空间，非常容易栈溢出&amp;lt;br&amp;gt;可能会存在大量的重复计算"></node><node CREATED="1747229326054" ID="ID_a7c5bfae85fd865a" MODIFIED="1747229326054" TEXT="如果能不用递归就尽量不要用递归。&amp;nbsp;&amp;lt;br&amp;gt;有时候写不出来，就先用递归写。&amp;nbsp;"></node></node></node></node></map>